 initCombat(){this.minions=new Map();this.neutrals=new Map();this.structures=new Map();this.combatProjectiles=[];this.nextUnit=100000;this.nextCombatProjectile=1;this.waveNumber=0;this.nextWave=10;this.waveLog=[];this.stealth=new StealthSystem(this.layout.bushes??[],this.heroes);this.blessings={Light:0,Dark:0};this.winner=null;this.routes=new Map(Object.entries(this.layout.lanes).map(([key,p])=>[key,new LaneRoute(p)]));
  for(const e of this.manifest.entities){if(['tower','nexus'].includes(e.category)){const nexus=e.category==='nexus',s={id:e.id,category:e.category,team:e.properties.team,lane:e.properties.lane,tier:e.properties.tier,position:xy(e.position),health:nexus?11000:e.properties.health,maxHealth:nexus?11000:e.properties.health,range:nexus?17:15.5,damage:nexus?150:120,period:nexus?.9:1.05,radius:nexus?3.4:2.65,alive:true,nextAttack:0,attackAt:-100,deadAt:null};this.structures.set(s.id,s);}
   if(['neutral','boss'].includes(e.category)){const kind=e.properties.monster_kind,stats=NEUTRAL_STATS[kind];if(!stats)throw new Error('Unknown neutral '+kind);const member=e.properties.member_index??0,ratio=member===0?1:.55,n={id:e.id,category:e.category,kind,team:'Neutral',position:xy(e.position),home:xy(e.position),health:stats.hp*ratio,maxHealth:stats.hp*ratio,damage:stats.damage*(member===0?1:.65),radius:e.category==='boss'?3.4:1.1,range:e.category==='boss'?7:2.5,speed:e.category==='boss'?2.3:3.0,alive:false,state:'Dormant',spawnAt:e.properties.spawn_seconds??(e.category==='boss'?(kind==='SolarColossus'?180:420):20),respawn:e.properties.respawn_seconds??stats.respawn,camp:e.properties.camp_index??0,target:null,attackAt:-100,nextAttack:0,deadAt:null,respawnAt:null};this.neutrals.set(n.id,n);}}
  for(const s of this.structures.values())for(let dz=-5;dz<=5;dz++)for(let dx=-5;dx<=5;dx++){const i=this.nav.index({x:s.position.x+dx,z:s.position.z+dz});if(i>=0)this.nav.mask[i]=this.nav.staticWalkable(this.nav.point(i))?1:0;}
 }
 updateVisibility(){this.stealth?.update(this.heroes,this.time);}
